export function makeEffects(){return{particles:[],slashes:[],burst(x,y,color){for(let i=0;i<9;i++){const a=Math.random()*Math.PI*2,s=35+Math.random()*90;this.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.45,max:.45,color});}},slash(x,y,dx,dy){this.slashes.push({x,y,dx,dy,life:.18});}};}
export function updateEffects(e,dt){for(const p of e.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=90*dt;p.life-=dt;}e.particles=e.particles.filter(p=>p.life>0);for(const s of e.slashes)s.life-=dt;e.slashes=e.slashes.filter(s=>s.life>0);}
export function drawEffects(c,e){for(const p of e.particles){c.globalAlpha=Math.max(0,p.life/p.max);c.fillStyle=p.color;c.fillRect(p.x|0,p.y|0,4,4);}c.globalAlpha=1;for(const s of e.slashes){c.strokeStyle='#fff0a6';c.lineWidth=4;c.globalAlpha=s.life/.18;c.beginPath();c.arc(s.x,s.y,27,Math.atan2(s.dy,s.dx)-.8,Math.atan2(s.dy,s.dx)+.8);c.stroke();}c.globalAlpha=1;}
